-- v4.4.10 governed model gateway, usage ledger, pricing, and wallboard.
DECLARE n NUMBER; BEGIN
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_GATEWAY_CREDENTIALS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_GATEWAY_CREDENTIALS (CREDENTIAL_ID VARCHAR2(128) PRIMARY KEY, DISPLAY_NAME VARCHAR2(160) NOT NULL, TOKEN_DIGEST VARCHAR2(128) UNIQUE NOT NULL, SCOPES_JSON CLOB NOT NULL, STATUS VARCHAR2(24) NOT NULL, EXPIRES_AT TIMESTAMP, CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, REVOKED_AT TIMESTAMP, REVOKED_BY VARCHAR2(128), REVOKE_REASON VARCHAR2(500))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_REQUESTS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_REQUESTS (REQUEST_ID VARCHAR2(128) PRIMARY KEY, ACTOR_PRINCIPAL_ID VARCHAR2(128) NOT NULL, AGENT_ID VARCHAR2(128), PROFILE_ID VARCHAR2(128) NOT NULL, MODEL_ID VARCHAR2(256) NOT NULL, STATUS VARCHAR2(24) NOT NULL, IDEMPOTENCY_KEY VARCHAR2(160), INPUT_DIGEST VARCHAR2(128) NOT NULL, ERROR_CATEGORY VARCHAR2(64), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, COMPLETED_AT TIMESTAMP, CONSTRAINT CX_MODEL_REQ_UQ UNIQUE(ACTOR_PRINCIPAL_ID,IDEMPOTENCY_KEY))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_PRICING'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_PRICING (PRICE_ID VARCHAR2(128) PRIMARY KEY, PRICING_VERSION VARCHAR2(64) NOT NULL, PROVIDER_KEY VARCHAR2(128) NOT NULL, MODEL_ID VARCHAR2(256) NOT NULL, CURRENCY VARCHAR2(12) NOT NULL, INPUT_PER_MILLION NUMBER(24,12), OUTPUT_PER_MILLION NUMBER(24,12), CACHE_PER_MILLION NUMBER(24,12), REASONING_PER_MILLION NUMBER(24,12), EFFECTIVE_FROM TIMESTAMP NOT NULL, EFFECTIVE_TO TIMESTAMP, STATUS VARCHAR2(24) NOT NULL)'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_USAGE'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_USAGE (USAGE_ID VARCHAR2(128) PRIMARY KEY, REQUEST_ID VARCHAR2(128) UNIQUE NOT NULL, ACTOR_PRINCIPAL_ID VARCHAR2(128) NOT NULL, AGENT_ID VARCHAR2(128), PROVIDER_KEY VARCHAR2(128) NOT NULL, MODEL_ID VARCHAR2(256) NOT NULL, PROMPT_TOKENS NUMBER, COMPLETION_TOKENS NUMBER, CACHED_TOKENS NUMBER, REASONING_TOKENS NUMBER, TOTAL_TOKENS NUMBER, USAGE_PROVENANCE VARCHAR2(32) NOT NULL, COST NUMBER(24,6), CURRENCY VARCHAR2(12), PRICING_VERSION VARCHAR2(64), STATUS VARCHAR2(24) NOT NULL, LATENCY_MS NUMBER NOT NULL, IDEMPOTENCY_KEY VARCHAR2(160), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_WALLBOARD_DEFINITIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_WALLBOARD_DEFINITIONS (DEFINITION_ID VARCHAR2(128) PRIMARY KEY, VERSION NUMBER NOT NULL, DISPLAY_NAME VARCHAR2(160) NOT NULL, CONFIG_JSON CLOB NOT NULL, SCOPE_JSON CLOB NOT NULL, STATUS VARCHAR2(24) NOT NULL, CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_ROUTING_POLICIES'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_ROUTING_POLICIES (POLICY_ID VARCHAR2(128) PRIMARY KEY, AGENT_ID VARCHAR2(128), PROFILE_ID VARCHAR2(128), ROUTING_MODE VARCHAR2(24) DEFAULT ''OPTIONAL'' NOT NULL, GATEWAY_ENABLED CHAR(1) DEFAULT ''N'' NOT NULL, DIRECT_ALLOWED CHAR(1) DEFAULT ''Y'' NOT NULL, UPDATED_BY VARCHAR2(128) NOT NULL, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, REASON VARCHAR2(500), CONSTRAINT CX_MODEL_ROUTE_UQ UNIQUE(AGENT_ID,PROFILE_ID))'; END IF;
END;
/
CREATE INDEX CX_MODEL_USAGE_SCOPE_TIME ON CX_MODEL_USAGE(ACTOR_PRINCIPAL_ID,CREATED_AT);
CREATE INDEX CX_MODEL_REQUESTS_AGENT_TIME ON CX_MODEL_REQUESTS(AGENT_ID,CREATED_AT);
